<div x-data="{selected:@js($selected??[]),query:'',type:'all',choices:@js(array_map(fn($c)=>['value'=>$c['kind'].':'.$c['id'],'label'=>$c['label'],'kind'=>$c['kind']],$choices)),limit:{{ $limit??20 }}}">
<template x-for="value in selected" :key="value"><input type="hidden" name="{{ $fieldName }}" :value="value"></template>
<div class="notes-actions mb-3"><template x-for="value in selected" :key="value"><button type="button" class="form-chip text-xs" @click="selected=selected.filter(v=>v!==value)" :aria-label="'Remove '+(choices.find(c=>c.value===value)?.label||value)"><span x-text="choices.find(c=>c.value===value)?.label||value"></span><span aria-hidden="true">×</span></button></template></div>
<details><summary>+ {{ $label??'Select items' }} · <span x-text="selected.length"></span> selected</summary><div class="notes-columns my-3"><input x-model="query" placeholder="Search…" aria-label="Search selectable items" class="theme-input"><select x-model="type" aria-label="Filter selectable item type" class="theme-input"><option value="all">All types</option>@foreach(array_keys(\App\Services\Planner\PlannerResources::TYPES) as $kind)<option value="{{ $kind }}">{{ ucfirst($kind) }}</option>@endforeach</select></div><p class="notes-hint mb-2">Select up to {{ $limit??20 }}. Click a selected chip to remove it.</p><div class="notes-stack" style="max-height:320px;overflow:auto;gap:10px"><template x-for="choice in choices" :key="choice.value"><label class="notes-actions text-sm" x-show="(type==='all'||type===choice.kind)&&choice.label.toLowerCase().includes(query.toLowerCase())"><input type="checkbox" x-model="selected" :value="choice.value" :disabled="selected.length>=limit&&!selected.includes(choice.value)"><span class="notes-priority" x-text="choice.kind"></span><span x-text="choice.label"></span></label></template></div></details>
</div>
